import { clean, CleanOptions } from 'typepurify';

export interface GuardOptions extends CleanOptions {
  strict?: boolean;
}

/**
 * StructuredOutputGuard safely extracts, repairs, and purifies JSON generated by LLMs.
 */
export class StructuredOutputGuard {
  static extractAndPurify<T = any>(rawText: string, options: GuardOptions = {}): T {
    const jsonString = StructuredOutputGuard.extractJsonString(rawText);
    if (!jsonString) {
      if (options.strict) {
        throw new Error('No valid JSON block detected in LLM output');
      }
      return {} as T;
    }

    const sanitized = StructuredOutputGuard.repairMalformedJson(jsonString);
    try {
      const parsed = JSON.parse(sanitized);
      return clean(parsed, options) as T;
    } catch (err: any) {
      if (options.strict) {
        throw new Error(`Failed to parse extracted LLM JSON: ${err.message}`);
      }
      return {} as T;
    }
  }

  static extractJsonString(raw: string): string | null {
    // 1. Check for markdown code fences ```json ... ``` or ``` ... ```
    const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (fenceMatch && fenceMatch[1]) {
      return fenceMatch[1].trim();
    }

    // 2. Locate first '{' or '[' and last matching '}' or ']'
    const firstBrace = raw.indexOf('{');
    const firstBracket = raw.indexOf('[');
    let startIdx = -1;

    if (firstBrace !== -1 && firstBracket !== -1) {
      startIdx = Math.min(firstBrace, firstBracket);
    } else {
      startIdx = firstBrace !== -1 ? firstBrace : firstBracket;
    }

    if (startIdx === -1) return null;

    const isObject = raw[startIdx] === '{';
    const endChar = isObject ? '}' : ']';
    const lastIdx = raw.lastIndexOf(endChar);

    if (lastIdx === -1 || lastIdx <= startIdx) return null;

    return raw.substring(startIdx, lastIdx + 1).trim();
  }

  static repairMalformedJson(json: string): string {
    return (
      json
        // Replace unquoted undefined with null
        .replace(/:\s*undefined\b/g, ': null')
        // Remove trailing commas before closing braces/brackets
        .replace(/,\s*([}\]])/g, '$1')
        // Remove Javascript single-line comments // ...
        .replace(/\/\/.*$/gm, '')
        .trim()
    );
  }
}
